from core import *
def main():
 summaries=[]
 for split in ['development','confirmation']:
  d=pd.read_csv(P/f'results/contamination_{split}.csv');bh=d.groupby(['heat_id','strategy']).mean(numeric_only=True).reset_index();bh.to_csv(P/f'results/{split}_per_heat.csv',index=False);d.groupby(['heat_id','band','strategy']).mean(numeric_only=True).reset_index().to_csv(P/f'results/{split}_per_heat_band.csv',index=False);d.groupby(['band','kind','strength','strategy']).mean(numeric_only=True).reset_index().to_csv(P/f'results/{split}_per_scenario.csv',index=False)
  for name,q in d.groupby('strategy'):
   counts=q[['tp','fp','fn','tn']].sum();p=float(counts.tp/max(counts.tp+counts.fp,1));r=float(counts.tp/max(counts.tp+counts.fn,1));g=bh[bh.strategy==name];m=g.mean(numeric_only=True);summaries.append(dict(split=split,strategy=name,precision=p,recall=r,f1=2*p*r/max(p+r,1e-12),false_positive_rate=float(counts.fp/max(counts.fp+counts.tn,1)),pollution_rmse=float(m.pollution_rmse),between_heat_pollution_SD=float(g.pollution_rmse.std()),before_pollution_rmse=float(m.before_pollution_rmse),overall_rmse=float(m.overall_rmse),before_overall_rmse=float(m.before_overall_rmse),unpolluted_rmse=float(m.unpolluted_rmse),unpolluted_changed_fraction=float(m.unpolluted_changed_fraction),peak_mean_relative=float(m.peak_mean_relative),integral_relative_mae=float(m.integral_relative_mae),introduced_unsupported_peak_count=int(q.introduced_unsupported_peak_count.sum()),loss=float(m.selection_loss),strict_fit_fraction=float(q.converged.mean())))
 pd.DataFrame(summaries).to_csv(P/'results/unified_comparison.csv',index=False)
 s=json.loads((P/'config/SELECTION_LOCKED.json').read_text());dump(P/'config/FINAL_MODEL_FROZEN.json',dict(strategy=s['strategy'],rank=4,eta=.003,score_threshold=4,automatic_component_time_span=3,automatic_component_wave_span=7,interpolation='bilinear',saturation='V3 recorded top codes and identical conditional tile objective',confirmation_evaluated=True,threshold_retuned_after_confirmation=False,reviewed_four_points='V31 evidence and local continuity; union with automatic repairs',no_more_detector_search=True,source_hashes={f:sha(P/'src'/f) for f in ['detectors.py','experiment_final.py','native_masks.py']}))
if __name__=='__main__':main()
